cale") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "updated_at" = EXCLUDED."updated_at", "room_layout" = EXCLUDED."room_layout", "faq" = EXCLUDED."faq", "ai_generated_name" = EXCLUDED."ai_generated_name", "ai_generated_description" = EXCLUDED."ai_generated_description", "ai_translated_from_name" = EXCLUDED."ai_translated_from_name", "ai_translated_from_description" = EXCLUDED."ai_translated_from_description", "client_requirements" = EXCLUDED."client_requirements", "foundation_options" = EXCLUDED."foundation_options", "technical_specs" = EXCLUDED."technical_specs", "construction_system" = EXCLUDED."construction_system", "roof_type" = EXCLUDED."roof_type", "customization_scope" = EXCLUDED."customization_scope", "service_scope_description" = EXCLUDED."service_scope_description";
